/**
 * A citation id resolved to catalogue metadata plus verbatim text.
 *
 * The metadata is projected from the registry legal catalogue (the single
 * citation authority); `verbatim_text` is read from the bundled extracted
 * corpus the citation's `corpus_ref` points at.
 */
export type CitationResolution = {
  citation_id: string;
  document_id: string;
  kind: string;
  corpus_ref: string;
  permalink: string;
  article: string | null;
  section: string | null;
  anchor: string | null;
  verbatim_text: string;
};

export type ContentDigest = string;

/**
 * Closed enumeration of CLI / API output language BCP-47 tags.
 *
 * The four members match the locale catalogues committed under
 * `src/cadrumo/locales/`. Adding a new operator-facing language requires
 * landing the catalogue first and then extending this enum so the loader-side
 * gates remain in sync.
 */
export type OutputLanguage = "es" | "en" | "ca" | "hu";

/**
 * Search the bundled reference corpus for free text or one exact citation id.
 */
export type ReferenceCorpusSearchRequest = {
  profile_id: string;
  query: string;
  output_language: OutputLanguage;
  limit?: number;
};

/**
 * What the bundled sources answer, bound to the profile and publication it was
 * read under.
 */
export type ReferenceCorpusSearchResult = {
  result_version: 1;
  profile_id: string;
  output_language: OutputLanguage;
  authority_generation: ContentDigest;
  retrieval: RetrievalResponse;
  terminology: TerminologyHit[];
};

/**
 * One ranked lexical-retrieval result over the corpus.
 *
 * `text` is the verbatim chunk prose (the snippet source); `corpus_ref`
 * grounds it in the bundled source (and is the `cadrumo://corpus/{ref}` key
 * that resolves the full verbatim text). `score` is the FTS5 BM25 relevance,
 * sign-flipped so a larger value is a better match; `lexical_rank` is the
 * hit's zero-based position in the lexical ranking.
 */
export type RetrievalHit = {
  chunk_id: string;
  corpus_ref: string;
  doc_title: string;
  text: string;
  score: number;
  rank: number;
  lexical_rank: number | null;
};

/**
 * How a retrieval response was produced.
 *
 * `CITATION` — the query was an exact citation id, short-circuited to the
 * structured lookup; `LEXICAL_ONLY` — the ranked FTS5 lexical search over the
 * bundled corpus. These are the only two shapes the product ships: the shipped
 * retrieval surface loads no model and computes no vectors.
 */
export type RetrievalMode = "citation" | "lexical_only";

/**
 * The typed result of one corpus retrieval.
 *
 * `mode` records how the response was produced (citation short-circuit or
 * ranked lexical search). `citation` carries the resolved citation when `mode`
 * is `CITATION`; otherwise `hits` carries the ranked results.
 */
export type RetrievalResponse = {
  query: string;
  mode: RetrievalMode;
  hits: RetrievalHit[];
  citation: CitationResolution | null;
};

/**
 * One ranked terminology search result.
 */
export type TerminologyHit = {
  concept_id: string;
  preferred_label: string;
  short_description: string;
  score: number;
  matched_on: string;
};

/** The registered request of "reference.corpus.search"; the host fills the profile. */
export type ReferenceRequest = ReferenceCorpusSearchRequest;

/** What the desktop host passes on of that read's result, under the product's own names. */
export type ReferenceServed = ReferenceCorpusSearchResult;
